import { readFile, writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
const catalog = JSON.parse(await readFile(new URL('../design-lab/icons/icons.json', import.meta.url), 'utf8'));
const destination = new URL('../app/android/app/src/main/java/app/mealgarden/FoodIconCatalog.kt', import.meta.url);
const literal = value => JSON.stringify(value);
const source = `package app.mealgarden

// Generated by scripts/generate-food-icons.mjs from the shared prototype/companion catalog.
internal data class FoodIconEntry(val id: String, val name: String, val category: String, val fallback: Boolean, val drawable: Int, val aliases: List<String>, val weakAliases: List<String>)
internal val foodIconCatalog = listOf(
${catalog.icons.map(icon => `    FoodIconEntry(${literal(icon.id)}, ${literal(icon.name)}, ${literal(icon.category)}, ${Boolean(icon.fallback)}, R.drawable.mg_${icon.id.replaceAll('-', '_')}, listOf(${icon.matchWords.map(literal).join(', ')}), listOf(${(icon.weakMatchWords ?? []).map(literal).join(', ')})),`).join('\n')}
)
`;
if (process.argv.includes('--check')) {
  if (await readFile(destination, 'utf8') !== source) throw new Error('FoodIconCatalog.kt is stale; run node scripts/generate-food-icons.mjs');
} else {
  await writeFile(destination, source);
  console.log(`Generated ${catalog.icons.length} icon mappings in ${fileURLToPath(destination)}`);
}
